/*
 * City soundtracks — four original instrumentals, one per theme, each a
 * 96-second loop. The bundled files are generated by scripts/ambient-score.js
 * (Tokyo) and scripts/theme-scores.js (the other cities); each render includes
 * a preroll that carries reverb and sustained notes across the loop seam.
 * Native audio-buffer looping needs no background JavaScript scheduler, and a
 * theme change crossfades on the audio clock instead of a JavaScript timer.
 */
(() => {
  'use strict';

  const SAMPLE_RATE = 44100;
  const METER_FRAMES = 32768;
  // Every bundled track peaks below 0.64, leaving headroom at full volume.
  // Keep amplification linear: waveshaping its peaks makes the music distort.
  const MAX_OUTPUT_GAIN = 1.50;
  const CROSSFADE = 0.35;
  const TRACKS = Object.freeze({
    tokyo: Object.freeze({ file: 'tokyo-afterimage.flac', title: 'Tokyo Afterimage · 東京残像', bpm: 80, duration: 96 }),
    kyoto: Object.freeze({ file: 'kyoto-lanterns.flac', title: 'Kyoto Lanterns · 京都灯籠', bpm: 60, duration: 96 }),
    okinawa: Object.freeze({ file: 'okinawa-island-time.flac', title: 'Okinawa Island Time · 沖縄島時間', bpm: 90, duration: 96 }),
    hokkaido: Object.freeze({ file: 'hokkaido-snowlight.flac', title: 'Hokkaido Snowlight · 北海道雪あかり', bpm: 75, duration: 96 }),
  });
  const DEFAULT_THEME = 'tokyo';
  const BASE_URL = document.currentScript?.src || document.baseURI;
  const trackUrl = theme => new URL(`./assets/${TRACKS[theme].file}`, BASE_URL).href;
  const normalizeTheme = value => typeof value === 'string' && Object.hasOwn(TRACKS, value) ? value : DEFAULT_THEME;
  const clamp = (value, low, high) => Math.max(low, Math.min(high, value));

  async function loadComposition(context, theme) {
    const track = TRACKS[theme];
    const response = await fetch(trackUrl(theme), { cache: 'force-cache' });
    if (!response.ok) throw new Error('背景音乐文件读取失败');
    const buffer = await context.decodeAudioData(await response.arrayBuffer());
    if (buffer.numberOfChannels !== 2 || Math.abs(buffer.duration - track.duration) > 0.01) {
      throw new Error('背景音乐文件格式不正确');
    }
    let peak = 0;
    let squareSum = 0;
    let measured = 0;
    // These are diagnostic estimates, not a playback limiter. Sample across
    // the track instead of blocking the renderer on millions of PCM values.
    const stride = Math.max(1, Math.ceil(buffer.length / METER_FRAMES));
    for (let channel = 0; channel < buffer.numberOfChannels; channel++) {
      const samples = buffer.getChannelData(channel);
      for (let index = 0; index < samples.length; index += stride) {
        peak = Math.max(peak, Math.abs(samples[index]));
        squareSum += samples[index] * samples[index];
        measured++;
      }
    }
    const rms = Math.sqrt(squareSum / measured);
    if (!Number.isFinite(peak) || peak < 0.0001 || !Number.isFinite(rms)) {
      throw new Error('背景音乐文件无有效声音');
    }
    return { theme, buffer, peak, rms };
  }

  function create({ onStatus } = {}) {
    let enabled = false;
    let volume = 90;
    let theme = DEFAULT_THEME;
    let context = null;
    let output = null;
    // The playing track: its buffer source, its own fader, its theme and the
    // decoded track it plays.
    let source = null;
    // Sources fading out after a theme change; they stop themselves.
    const retiring = new Set();
    // The decoded track for the current theme, and decodes still in flight,
    // one per city, shared by every start() that asks for it.
    let loaded = null;
    const loading = new Map();
    let pauseTimer = null;
    let suspension = null;
    let disposed = false;
    let startingAt = 0;
    // Where playback resumes, and which city's loop that position belongs to.
    let offset = 0;
    let offsetTheme = DEFAULT_THEME;
    let state = 'paused';
    let gestureRetried = false;
    let error = null;
    const wanted = () => enabled && volume > 0 && !disposed;
    const getStatus = () => {
      const track = TRACKS[theme];
      // Describe the chosen city only, not the one still playing while it loads.
      const current = loaded?.theme === theme ? loaded : null;
      return {
        state,
        theme,
        title: track.title,
        musicEnabled: enabled,
        musicVolume: volume,
        contextState: context?.state || 'uninitialized',
        currentTime: context?.currentTime || 0,
        playbackSeconds: source?.theme === theme ? (offset + Math.max(0, context.currentTime - startingAt)) % track.duration : offsetTheme === theme ? offset : 0,
        ready: Boolean(current),
        activeSources: (source ? 1 : 0) + retiring.size,
        tempoBpm: track.bpm,
        durationSeconds: track.duration,
        sampleRate: current?.buffer.sampleRate || null,
        peak: current?.peak || 0,
        rms: current?.rms || 0,
        error
      };
    };
    function publish(next, message = null) {
      state = next;
      if (next === 'playing') gestureRetried = false;
      error = message;
      if (typeof onStatus === 'function') {
        try { onStatus(getStatus()); } catch (_) { /* UI callbacks must not stop audio. */ }
      }
    }
    function cancelPause() {
      if (pauseTimer !== null) window.clearTimeout(pauseTimer);
      pauseTimer = null;
    }
    function ensureContext() {
      if (context) return context;
      const Context = window.AudioContext || window.webkitAudioContext;
      if (!Context) throw new Error('此设备不支持背景音乐播放');
      // Decode at the bundled tracks' native rate instead of resampling the
      // entire 96-second buffer to the audio device's rate before first play.
      context = new Context({ latencyHint: 'playback', sampleRate: SAMPLE_RATE });
      output = context.createGain();
      output.gain.value = 0;
      output.connect(context.destination);
      context.onstatechange = () => {
        if (disposed) return;
        if (wanted() && source && context.state === 'running') publish('playing');
        else if (wanted() && context.state !== 'running' && state !== 'starting') publish('blocked');
        else if (!wanted()) publish('paused');
      };
      return context;
    }
    function glide(param, target, timeConstant) {
      if (!context || context.state === 'closed') return;
      const now = context.currentTime;
      if (typeof param.cancelAndHoldAtTime === 'function') param.cancelAndHoldAtTime(now);
      else {
        param.cancelScheduledValues(now);
        param.setValueAtTime(param.value, now);
      }
      param.setTargetAtTime(target, now, timeConstant);
    }
    const fade = (target, timeConstant) => { if (output) glide(output.gain, target, timeConstant); };
    function release(entry) {
      try { entry.node.stop(); } catch (_) { /* Already stopped during page close. */ }
      entry.node.disconnect();
      entry.gain.disconnect();
      retiring.delete(entry);
    }
    function stopSource() {
      for (const entry of [...retiring]) release(entry);
      if (!source) return;
      offset = (offset + Math.max(0, context.currentTime - startingAt)) % TRACKS[source.theme].duration;
      offsetTheme = source.theme;
      release(source);
      source = null;
    }
    // Fade the current track out on the audio clock and let it end itself.
    function retireSource() {
      if (!source) return;
      const entry = source;
      source = null;
      retiring.add(entry);
      glide(entry.gain.gain, 0, CROSSFADE / 3);
      entry.node.onended = () => { if (retiring.has(entry)) release(entry); };
      try { entry.node.stop(context.currentTime + CROSSFADE * 3); } catch (_) { release(entry); }
    }
    function loadTrack(ctx, requested) {
      if (loaded?.theme === requested) return Promise.resolve(loaded);
      // A city still sounding, such as one fading out after a preview, lends
      // its buffer instead of decoding a second copy.
      const sounding = [source, ...retiring].find(entry => entry?.theme === requested);
      if (sounding) return Promise.resolve(loaded = sounding.track);
      // Previewing A, B and A again shares A's decode instead of starting another.
      if (loading.has(requested)) return loading.get(requested);
      const promise = loadComposition(ctx, requested).then(result => {
        // Keep only the track that is still wanted; a theme change while
        // decoding releases the older buffer instead of holding two.
        if (!disposed && requested === theme && loaded?.theme !== requested) loaded = result;
        return loaded?.theme === requested ? loaded : result;
      }).finally(() => loading.delete(requested));
      loading.set(requested, promise);
      return promise;
    }
    function pause() {
      cancelPause();
      fade(0, 0.10);
      publish('paused');
      if (!context || context.state === 'closed') return;
      // The fade is scheduled on the audio clock, even in a throttled window.
      pauseTimer = window.setTimeout(() => {
        pauseTimer = null;
        if (wanted() || disposed) return;
        stopSource();
        if (loaded && loaded.theme !== theme) loaded = null;
        if (context.state === 'running') {
          suspension = context.suspend().catch(() => {}).finally(() => {
            suspension = null;
            if (!wanted() && !disposed) publish('paused');
          });
        } else publish('paused');
      }, 550);
    }
    async function start(resuming) {
      if (!wanted()) return;
      cancelPause();
      if (source?.theme === theme && context?.state === 'running') {
        fade(volume / 100 * MAX_OUTPUT_GAIN, 0.12);
        publish('playing');
        return;
      }
      const requested = theme;
      publish('starting');
      try {
        const ctx = ensureContext();
        // The desktop window allows autoplay. Resume and decode in parallel
        // as soon as the saved preferences enable music.
        const resume = resuming || (ctx.state === 'running' ? Promise.resolve() : ctx.resume());
        const [, track] = await Promise.all([resume, loadTrack(ctx, requested)]);
        // A newer theme or preference change owns playback from here.
        if (!wanted() || requested !== theme) return;
        if (suspension) await suspension;
        if (!wanted() || requested !== theme) return;
        if (ctx.state !== 'running') await ctx.resume();
        if (!wanted() || requested !== theme) return;
        if (ctx.state !== 'running') {
          publish('blocked');
          return;
        }
        if (source && source.theme !== requested) retireSource();
        if (!source) {
          const crossfading = retiring.size > 0;
          const node = ctx.createBufferSource();
          const gain = ctx.createGain();
          node.buffer = track.buffer;
          node.loop = true;
          node.loopStart = 0;
          node.loopEnd = TRACKS[requested].duration;
          gain.gain.value = crossfading ? 0 : 1;
          node.connect(gain);
          gain.connect(output);
          source = { node, gain, theme: requested, track };
          loaded = track;
          // A city resumes where it paused; switching cities starts at the top.
          offset = offsetTheme === requested ? offset : 0;
          offsetTheme = requested;
          startingAt = ctx.currentTime;
          node.start(startingAt, offset);
          if (crossfading) glide(gain.gain, 1, CROSSFADE / 2);
        }
        fade(volume / 100 * MAX_OUTPUT_GAIN, 0.32);
        publish('playing');
      } catch (failure) {
        if (disposed || !wanted() || requested !== theme) return;
        // A previous city stops too, so what plays matches the status.
        if (source && source.theme !== requested) retireSource();
        const blocked = failure?.name === 'NotAllowedError' || context?.state === 'suspended';
        publish(blocked ? 'blocked' : 'error', blocked ? null : String(failure?.message || failure));
      }
    }
    function setPreferences(preferences = {}) {
      if (disposed) return;
      const nextEnabled = typeof preferences.musicEnabled === 'boolean' ? preferences.musicEnabled : enabled;
      const candidate = Number(preferences.musicVolume);
      const nextVolume = preferences.musicVolume !== undefined && Number.isFinite(candidate) ? clamp(candidate, 0, 100) : volume;
      const nextTheme = preferences.theme !== undefined ? normalizeTheme(preferences.theme) : theme;
      if (enabled === nextEnabled && volume === nextVolume && theme === nextTheme) return;
      if (theme !== nextTheme) {
        theme = nextTheme;
        // Without a playing source, release the other city's decoded buffer.
        if (!source && loaded && loaded.theme !== theme) loaded = null;
      }
      enabled = nextEnabled;
      volume = nextVolume;
      gestureRetried = false;
      if (wanted()) void start();
      else pause();
    }
    function unlock() {
      // A gesture may retry interrupted playback, but is never required to
      // start enabled music and must not activate disabled or muted music.
      if (!wanted()) return Promise.resolve();
      if (context?.state === 'running' && (source?.theme === theme || state === 'starting')) return Promise.resolve();
      // A failed start gets one more try from the next gesture. If that fails
      // too, turning music back on or choosing another city retries, as its
      // status says; retrying on every key press would fetch and decode the
      // track each time.
      if (state === 'error') {
        if (gestureRetried) return Promise.resolve();
        gestureRetried = true;
      }
      let resuming;
      try {
        const ctx = ensureContext();
        resuming = ctx.state === 'running' ? Promise.resolve() : ctx.resume();
      } catch (failure) {
        publish('error', String(failure?.message || failure));
        return Promise.resolve();
      }
      return start(resuming);
    }
    function dispose() {
      if (disposed) return;
      disposed = true;
      cancelPause();
      if (context) stopSource();
      if (context) {
        context.onstatechange = null;
        if (context.state !== 'closed') void context.close().catch(() => {});
      }
      if (output) output.disconnect();
      loaded = null;
      loading.clear();
      window.removeEventListener('pagehide', dispose);
      publish('paused');
    }
    window.addEventListener('pagehide', dispose, { once: true });
    return Object.freeze({ setPreferences, unlock, dispose, getStatus });
  }

  window.TokyoAmbience = Object.freeze({ create, tracks: TRACKS });
})();
